class PrimeTest {
    @Test
    void zeroIsNotPrime() {
        assertFalse(isPrime(0));
    }

    @Test
    void oneIsNotPrime() {
        assertFalse(isPrime(1));
    }

    @Test
    void negativeNumbersAreNotPrime() {
        assertFalse(isPrime(-7));
    }

    @Test
    void primeNumbersReturnTrue() {
        assertTrue(isPrime(2));
        assertTrue(isPrime(13));
        assertTrue(isPrime(37));
    }

    @Test
